#!/usr/bin/env python3
from pathlib import Path
import base64, zlib, re, sys

PATH = Path("src/index.source.html")
MARKER = "DIRECT_FINAL_V1"

def dec(data):
    return zlib.decompress(base64.b64decode(data)).decode("utf-8")

CORE = dec("")
ROAD = dec("")
PET = dec("")
EVENT = dec("")

text = PATH.read_text(encoding="utf-8")
if MARKER in text:
    print("Direct final patch already applied.")
    sys.exit(0)

# Keep the editable source using URL-based libraries/assets; only copy game/runtime sections.
text, n1 = re.subn(r"  var scene=new THREE\.Scene\(\);.*?(?=  var gray=new THREE\.MeshStandardMaterial)", lambda m: CORE, text, count=1, flags=re.S)
text, n2 = re.subn(r"  var gray=new THREE\.MeshStandardMaterial.*?(?=  var vehicleRoot=new THREE\.Group\(\);)", lambda m: ROAD, text, count=1, flags=re.S)
text, n3 = re.subn(r"  var petRoot=new THREE\.Group\(\).*?(?=  var gltfLoader=new THREE\.GLTFLoader\(\);)", lambda m: PET, text, count=1, flags=re.S)
text, n4 = re.subn(r"  var bubble=document\.getElementById\('bubble'\).*?  animate\(\);", lambda m: EVENT, text, count=1, flags=re.S)

if [n1,n2,n3,n4] != [1,1,1,1]:
    raise RuntimeError(f"Patch anchors failed: core={n1} road={n2} pet={n3} event={n4}")

# Final 5-second blackout overlay.
if '#finalBlackout{' not in text:
    text = text.replace('@media(pointer:fine){.pad{display:none}}', '#finalBlackout{position:fixed;inset:0;background:#000;opacity:0;pointer-events:none;z-index:50;transition:opacity 1.25s ease}\n#finalBlackout.show{opacity:1}\n@media(pointer:fine){.pad{display:none}}', 1)
if '<div id="finalBlackout"></div>' not in text:
    text = text.replace('<div id="stage"></div>', '<div id="stage"></div>\n<div id="finalBlackout"></div>', 1)
text = text.replace('<div id="hint">WASD / 왼쪽 패드로 이동</div>', '<div id="hint">ENDLESS DRIVE · 위험 감지 → 메시지 낙하</div>')
text = text.replace('<title>PLEASE STOP, GPT</title>', '<title>PLEASE STOP, GPT</title>\n<!-- '+MARKER+' -->', 1)

PATH.write_text(text, encoding="utf-8")
print("Applied", MARKER, "to", PATH)
